<?php
declare(strict_types=1);
function dto_image_absolute(array $p): string { return absolute_url(image_url(mediaos_primary_file($p))); }
function public_product_dto(array $p): array { return ['id'=>$p['guid'],'sku'=>$p['sku'],'slug'=>$p['slug'],'name'=>$p['name'],'short'=>$p['short'],'category'=>$p['category_label'],'collection'=>$p['collection'],'price'=>(int)$p['price'],'currency'=>'INR','image'=>dto_image_absolute($p),'materials'=>array_values((array)($p['materials']??[])),'finishes'=>array_values((array)($p['finishes']??[])),'dimensions'=>$p['dimensions'],'lead_time'=>$p['lead_time'],'url'=>absolute_url('/product/'.$p['slug'])]; }
function merchant_product_dto(array $p): array { $inStock=empty($p['inventory']['track'])||!empty($p['inventory']['made_to_order'])||(int)($p['inventory']['stock']??0)>0;return ['id'=>$p['sku'],'title'=>$p['name'],'description'=>$p['short'],'link'=>absolute_url('/product/'.$p['slug']),'image_link'=>dto_image_absolute($p),'availability'=>$inStock?'in_stock':'out_of_stock','price'=>(int)$p['price'].' INR','brand'=>'Atelier Wood','condition'=>'new','product_type'=>(string)($p['category_label']??$p['category']??''),'custom_label_0'=>$p['category_label'],'custom_label_1'=>$p['collection']]; }
function ai_product_dto(array $p): array { return ['product_id'=>$p['guid'],'sku'=>$p['sku'],'brand'=>'Atelier Wood','name'=>$p['name'],'summary'=>$p['short'],'description'=>$p['description']??$p['short'],'category'=>$p['category_label'],'collection'=>$p['collection'],'price'=>['amount'=>(int)$p['price'],'currency'=>'INR'],'material_options'=>array_values((array)($p['materials']??[])),'finish_options'=>array_values((array)($p['finishes']??[])),'dimensions'=>$p['dimensions'],'availability'=>seo_product_available($p)?'in_stock':'out_of_stock','made_to_order'=>(bool)($p['inventory']['made_to_order']??false),'customisable'=>(bool)($p['customisation']['enabled']??false),'lead_time'=>$p['lead_time'],'image'=>dto_image_absolute($p),'canonical_url'=>absolute_url('/product/'.$p['slug'])]; }
function agent_product_dto(array $p): array { $d=ai_product_dto($p);$d['sku']=$p['sku'];$d['care']=$p['care']??'';$d['warranty']=$p['warranty']??'';return$d; }
function integration_public_catalog(string $q=''): array { $q=text_lower(trim($q));$rows=[];foreach(products_public() as $p){if($q!==''&&!str_contains(text_lower($p['name'].' '.$p['short'].' '.$p['category_label'].' '.implode(' ',(array)($p['tags']??[]))),$q))continue;$rows[]=public_product_dto($p);}return$rows; }
function merchant_xml(): string {
    $esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_XML1,'UTF-8');
    $xml="<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<rss version=\"2.0\" xmlns:g=\"http://base.google.com/ns/1.0\"><channel>";
    $xml.='<title>Atelier Wood</title><link>'.$esc(absolute_url('/')).'</link><description>Atelier Wood product feed</description>';
    foreach(products_public() as $p){$d=merchant_product_dto($p);$xml.='<item>';
        foreach($d as $k=>$v){$tag=in_array($k,['title','description','link'],true)?$k:'g:'.$k;$xml.='<'.$tag.'>'.$esc($v).'</'.$tag.'>';}
        $xml.='</item>';}
    return $xml.'</channel></rss>';
}

function agent_signing_key(): string { $k=trim((string)getenv('ATELIER_AGENT_SIGNING_KEY'));if($k==='')$k=trim((string)($GLOBALS['app']['agent_signing_key']??''));return$k; }
function b64u(string $s): string { return rtrim(strtr(base64_encode($s),'+/','-_'),'='); }
function b64u_dec(string $s): string|false { $pad=(4-strlen($s)%4)%4;return base64_decode(strtr($s.str_repeat('=',$pad),'-_','+/'),true); }
function agent_issue_token(array $scopes=['orders:read'],int $ttl=900): string { require_customer('/account');$key=agent_signing_key();if(strlen($key)<32)throw new RuntimeException('ATELIER_AGENT_SIGNING_KEY must be at least 32 characters.');$allowed=['orders:read','profile:read'];$scopes=array_values(array_intersect($allowed,$scopes));$payload=['sub'=>(string)customer_identity()['guid'],'aud'=>'atelierwood-agent','scope'=>$scopes,'iat'=>time(),'exp'=>time()+max(60,min(1800,$ttl)),'jti'=>bin2hex(random_bytes(8))];$body=b64u(json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$sig=b64u(hash_hmac('sha256',$body,$key,true));return$body.'.'.$sig; }
function agent_validate_token(string $token,string $scope): array { $parts=explode('.',$token);if(count($parts)!==2)throw new RuntimeException('Invalid agent token.');[$body,$sig]=$parts;$key=agent_signing_key();if(strlen($key)<32)throw new RuntimeException('Agent signing key unavailable.');$expect=b64u(hash_hmac('sha256',$body,$key,true));if(!hash_equals($expect,$sig))throw new RuntimeException('Agent token signature invalid.');$raw=b64u_dec($body);$p=json_decode((string)$raw,true);if(!is_array($p)||($p['aud']??'')!=='atelierwood-agent'||(int)($p['exp']??0)<time())throw new RuntimeException('Agent token expired or invalid.');if(!in_array($scope,(array)($p['scope']??[]),true))throw new RuntimeException('Agent token scope denied.');return$p; }
function bearer_token(): string { $h=(string)($_SERVER['HTTP_AUTHORIZATION']??'');return preg_match('/^Bearer\s+(.+)$/i',$h,$m)?trim($m[1]):''; }
function agent_order_dto(array $o): array { return ['order_id'=>$o['guid'],'number'=>$o['number'],'status'=>$o['status'],'payment_status'=>$o['payment_status'],'total'=>$o['pricing']['grand_total'],'currency'=>'INR','items'=>array_map(fn($i)=>['sku'=>$i['sku'],'name'=>$i['name'],'qty'=>$i['qty'],'material'=>$i['material'],'finish'=>$i['finish']],$o['items']),'created_at'=>$o['created_at'],'updated_at'=>$o['updated_at']]; }
function integrations_release_checks(): array { $secretFields=['cost','supplier','customer_guid','password_hash','address_snapshot'];$leak=false;foreach(products_public() as $p){$json=json_encode([public_product_dto($p),merchant_product_dto($p),ai_product_dto($p),agent_product_dto($p)]);foreach($secretFields as $f)if(str_contains((string)$json,'"'.$f.'"'))$leak=true;}return [
 ['name'=>'External serializer allowlist','ok'=>!$leak,'detail'=>!$leak?'Public/Merchant/AI/agent product serializers exclude private/internal fields.':'External serializer leakage detected.'],
 ['name'=>'Merchant feed generation','ok'=>str_contains(merchant_xml(),'<rss'),'detail'=>'Google Merchant-compatible XML projection generates from public catalogue.'],
 ['name'=>'AI product feed coverage','ok'=>count(products_public())===count(array_map('ai_product_dto',products_public())),'detail'=>'AI-readable feed covers every active public product.'],
 ['name'=>'Agent signing key','ok'=>strlen(agent_signing_key())>=32,'detail'=>strlen(agent_signing_key())>=32?'Agent token signing key is configured.':'Configure ATELIER_AGENT_SIGNING_KEY (32+ characters) before using authenticated agent tools.'],
]; }
